def best_dist(o):
    h,w=out.shape; H,W=o.shape
    best=(99,None)
    for name,t in tf(out):
        for r in range(H-h+1):
            for c in range(W-w+1):
                d=np.sum(o[r:r+h,c:c+w]!=t)+ (o.sum()-t.sum())
                # only count mismatch where either is 1 in window plus extra cells outside
                extra=o.sum()-t.sum()
                best=min(best,(d+extra,(name,r,c)))
    return best
